# >>> STATIC
_static_msbuild_clp() {
    cat <<-'ARGCEOF'
	PerformanceSummary	Show time spent in tasks, targets and projects
	Summary	Show error and warning summary at the end
	NoSummary	Don't show error and warning summary at the end
	ErrorsOnly	Show only errors
	WarningsOnly	Show only warnings
	NoItemAndPropertyList	Don't show list of items and properties at the start of each project build
	ShowCommandLine	Show TaskCommandLineEvent messages
	ShowTimestamp	Display the Timestamp as a prefix to any message
	ShowEventId	Show eventId for started events, finished events, and messages
	ForceNoAlign	Does not align the text to the size of the console buffer
	DisableConsoleColor	Use the default console colors for all logging messages
	EnableMPLogging	Enable the multiprocessor logging style even when running in non-multiprocessor mode
	ForceConsoleColor	Use ANSI console colors even if console does not support it
	PreferConsoleColor	Use ANSI console colors only if target console does support it
	Verbosity	overrides the -verbosity setting for this logger
ARGCEOF
}

_static_msbuild_tlp() {
    cat <<-'ARGCEOF'
	default	Specifies the default behavior of the terminal logger
	verbosity	Override the -verbosity setting for this logger
	showCommandLine	Show TaskCommandLineEvent messages
ARGCEOF
}

_static_msbuild_nr() {
    cat <<-'ARGCEOF'
	True	Nodes will remain after the build completes and will be reused by subsequent builds (default)
	False	Nodes will not remain after the build completes
ARGCEOF
}

_static_vstest_TestAdapterLoadingStrategy() {
    cat <<-'ARGCEOF'
	Explicit	Test Platform will only load adapters specified by /TestAdapterPath (or RunConfiguration.TestAdaptersPaths node)
	Default	Test Platform will load adapters is if this argument has not been specified
	DefaultRuntimeProviders	Load default runtime providers shipped with Test Platform
	ExtensionsDirectory	Load adapters inside Extensions folder
	NextToSource	Load adapters next to source
	Recursive	Recursively search folders when loading adapters
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_dotnet_configuration() {
    local proj configs
    proj="$(_helper_dotnet_project)" || proj=
    if [[ -n "$proj" ]]; then
        configs="$(grep -oE '<Configurations>[^<]+</Configurations>' "$proj" 2>/dev/null | sed -E 's/.*>([^<]+)<.*/\1/')"
        if [[ -n "$configs" ]]; then
            printf '%s\n' "$configs" | tr ';' '\n'
            return 0
        fi
    fi
    printf '%s\n' Debug Release
}

_choice_dotnet_framework() {
    local proj tfms
    proj="$(_helper_dotnet_project)" || proj=
    if [[ -n "$proj" ]]; then
        tfms="$(grep -oE '<TargetFrameworks?>[^<]+</TargetFrameworks?>' "$proj" 2>/dev/null | sed -E 's/.*>([^<]+)<.*/\1/')"
        if [[ -n "$tfms" ]]; then
            printf '%s\n' "$tfms" | tr ';' '\n'
            return 0
        fi
    fi
    dotnet --list-runtimes 2>/dev/null | gawk '$1 == "Microsoft.NETCore.App" { split($2, v, "."); print "net" v[1] "." v[2] }'
}

_choice_dotnet_launch_profile() {
    local dir="$PWD" file
    while :; do
        file="$dir/Properties/launchSettings.json"
        if [[ -f "$file" ]]; then
            jq -b -r '(.profiles // {}) | keys[]' "$file" 2>/dev/null
            return 0
        fi
        [[ "$dir" == "/" || -z "$dir" ]] && break
        dir="$(dirname "$dir")"
    done
}

_choice_dotnet_nuget_source() {
    dotnet nuget list source --format detailed 2>/dev/null | gawk '/^[[:space:]]*[0-9]+\. / { line = $0; sub(/^[[:space:]]*[0-9]+\. /, "", line); sub(/ \[.*/, "", line); print line }'
}

_choice_dotnet_runtime() {
    local proj rids
    proj="$(_helper_dotnet_project)" || proj=
    if [[ -n "$proj" ]]; then
        rids="$(grep -oE '<RuntimeIdentifiers?>[^<]+</RuntimeIdentifiers?>' "$proj" 2>/dev/null | sed -E 's/.*>([^<]+)<.*/\1/')"
        if [[ -n "$rids" ]]; then
            printf '%s\n' "$rids" | tr ';' '\n'
            return 0
        fi
    fi
    dotnet --info 2>/dev/null | gawk '/^[[:space:]]*RID:/ { print $2; exit }'
}

_choice_dotnet_template() {
    dotnet new list 2>/dev/null | gawk -F'  +' '/^-----/ { header = 1; next } header && NF >= 2 { print $2 }' | tr ',' '\n'
}

_choice_dotnet_tool() {
    { dotnet tool list -g 2>/dev/null; dotnet tool list 2>/dev/null; } | gawk 'NF && $1 !~ /^(Package|-----)/ { print $1 }'
}

_choice_dotnet_tool_command() {
    { dotnet tool list -g 2>/dev/null; dotnet tool list 2>/dev/null; } | gawk 'NF >= 3 && $1 !~ /^(Package|-----)/ { print $3 }' | tr ',' '\n'
}

_choice_dotnet_verbosity() {
    printf '%s\n' quiet minimal normal detailed diagnostic q m n d diag
}

_choice_dotnet_workload() {
    dotnet workload search 2>/dev/null | gawk '/^-----/ { header = 1; next } header && NF { print $1 }'
}

_helper_dotnet_project() {
    local dir="$PWD" proj
    while :; do
        for proj in "$dir"/*.csproj "$dir"/*.fsproj "$dir"/*.vbproj; do
            if [[ -f "$proj" ]]; then
                printf '%s\n' "$proj"
                return 0
            fi
        done
        [[ "$dir" == "/" || -z "$dir" ]] && break
        dir="$(dirname "$dir")"
    done
    return 1
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
